'use strict';
const assert=require('assert'),G=require('./engine'),results=[];
function test(name,fn){try{fn();results.push({name,pass:true});}catch(e){results.push({name,pass:false,error:e.message});}}
const payload=q=>({question_id:q,field_contract:Object.fromEntries(Object.entries(G.fields).filter(([id])=>id.startsWith(q+'-'))),sources:[{id:'one',text:'我是慢热的人。',question_id:q,question:G.baseQuestion[q],speaker:'narrator'}],previous_fields:{},evidence_units:[]});
test('ordinary text is classified in context instead of guessing an action',()=>{const r=G.controlStep(payload('SK05'));assert.equal(r.needs_model,true);assert(!r.proposal);assert.equal(r.payload.task,'classify_current_interview_control');});
for(const text of ['先暂停一下','我们休息一下','今天就聊到这里','不聊了','采访结束','我累了','这一题不想讲','换个问题','下一题','这题下次再讲','以后再说','改天再谈','回头说','往后再聊','先放一放','暂时不讲'])test('potential control marker is classified, never auto chosen:'+text,()=>{const p=payload('SK05');p.sources[0].text=text;const r=G.controlStep(p);assert.equal(r.needs_model,true);assert(!r.proposal);assert.equal(r.payload.sources[0].text,text);});
test('no source never fabricates continue',()=>{const p=payload('SK05');p.sources=[];assert.equal(G.controlStep(p).proposal.control,null);});
test('required self trait and input reported trait precede untriggered clarifications',()=>{const p=payload('SK05'),ids=G.stepFrontier(p,{fields:{},active:['SK05-E1']},[]).map(x=>x.field_id);assert.deepEqual(ids,['SK05-E1','SK05-R1']);});
test('self trait ready does not schedule inactive conditional followups',()=>{const p=payload('SK05'),r={fields:{'SK05-E1':{state:'known'}},active:[]};assert.equal(G.stepFrontier(p,r,['SK05-E1','SK05-R1']).length,0);});
test('reported trait can activate its own stance check',()=>{const p=payload('SK05'),r={fields:{'SK05-R1':{state:'known'}},active:['SK05-E2']};assert.deepEqual(G.stepFrontier(p,r,['SK05-E1','SK05-R1']).map(x=>x.field_id),['SK05-E2']);});
test('linked reason waits for an already-validated same-question work selection',()=>{const p=payload('WK01');let r={fields:{},active:[]};assert.deepEqual(G.stepFrontier(p,r,[]).map(x=>x.field_id),['WK01-E1']);r={fields:{'WK01-E1':{state:'known',value:'原话工作'}},active:['WK01-E2']};const next=G.stepFrontier(p,r,['WK01-E1']);assert.equal(next[0].field_id,'WK01-E2');assert.equal(next[0].payload.related_fields['WK01-E1'].value,'原话工作');});
test('explicit premise absence prevents irrelevant detailed extraction',()=>{const p=payload('FM01');assert.deepEqual(G.stepFrontier(p,{fields:{},active:[]},[]).map(x=>x.field_id),['FM01-A1']);assert.equal(G.stepFrontier(p,{fields:{'FM01-A1':{state:'none'}},active:['FM01-A1']},['FM01-A1']).length,0);});
test('foreign question dependency is rejected',()=>{const p=payload('SK05');assert.throws(()=>G.stepFrontier(p,{fields:{},active:[]},['SK04-E1']));});
const report={kind:'synthetic_same_question_field_steps',tests:results.length,passed:results.filter(r=>r.pass).length,failed:results.filter(r=>!r.pass),no_DS_calls:true};console.log(JSON.stringify(report,null,2));process.exitCode=report.failed.length?1:0;
